use std::io::*;

fn eval(line: &str) -> String {
    let mut st: Vec<i64> = Vec::new();
    for t in line.split_whitespace() {
        match t {
            "+" | "-" | "*" | "/" => {
                if st.len() < 2 {
                    return "error: underflow".into();
                }
                let b = st.pop().unwrap();
                let a = st.pop().unwrap();
                let r = match t {
                    "+" => a.wrapping_add(b),
                    "-" => a.wrapping_sub(b),
                    "*" => a.wrapping_mul(b),
                    _ => {
                        if b == 0 {
                            return "error: divzero".into();
                        }
                        a.wrapping_div(b)
                    }
                };
                st.push(r);
            }
            _ => {
                let d = t.strip_prefix('-').unwrap_or(t);
                if d.is_empty() || !d.bytes().all(|c| c.is_ascii_digit()) {
                    return "error: token".into();
                }
                match t.parse::<i64>() {
                    Ok(v) => st.push(v),
                    Err(_) => return "error: token".into(),
                }
            }
        }
    }
    if st.len() == 1 {
        st[0].to_string()
    } else {
        "error: leftover".into()
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut o = String::new();
    for l in s.lines() {
        if l.trim().is_empty() {
            continue;
        }
        o.push_str(&eval(l));
        o.push('\n');
    }
    print!("{}", o);
}

